variables.code:
x = 10;
(* Delayed assignment: recalculates every time *)
y := RandomReal[]

data_types.code:
int = 42;
real = 3.14159;
comp = 1 + 2 I;
rat = 3 / 4;
str = "string";
sym = x; (* symbolic variable *)

arrays.code:
vec = {1.5, 2.3, 4.1};
mat = {{1, 2, 3}, {4, 5, 6}};

(* Accessing (1-based indexing) *)
val = mat[[1, 2]];

(* Slicing *)
col = mat[[All, 2]];

maps.code:
assoc = <|"a" -> 1, "b" -> 2|>;

(* Accessing *)
val = assoc["a"];

(* Updating *)
AppendTo[assoc, "c" -> 3];
